TEMPLE = lambda at=0.0, id='tmp': prop('temple', 0.62, 0.84, at, id, h=330)
def stamp(text, x=0.64, y=0.62, at=0.0, id='stp', h=150): return prop('stamp', x, y, at, id, h=h, kw={'text': text})
def flagrow(specs, y=0.5, x0=0.48, dx=0.14, s=90, pre='fl'):
    return [badge('flag-' + f, S(x0 + i * dx, y), at, lbl, f'{pre}{i}', s=s) for i, (f, at, lbl) in enumerate(specs)]
